// `auth generate` overwrites src/core/db/schema/auth.ts wholesale, deleting the hand-written "do not
// edit by hand" notice in the repo — anyone running `pnpm auth:generate` would see a puzzling one-line
// diff. After generation, put the notice back on the first line (leave it if already there) so the
// output of `pnpm auth:generate` matches what's in the repo. Called from auth:generate in package.json.
import { readFileSync, writeFileSync } from "node:fs";

const header =
  "// Generated by the Better Auth CLI (pnpm auth:generate); do not edit by hand. After changing plugins or fields, regenerate, then run pnpm db:generate.";

const file = process.argv[2];
if (!file) {
  console.error("usage: node scripts/auth-schema-header.mjs <file>");
  process.exit(1);
}

const source = readFileSync(file, "utf8");
if (!source.startsWith(header)) {
  writeFileSync(file, `${header}\n${source}`);
}
